hudson.tasks.Shell.command:
#!/usr/bin/env bash set -euo pipefail NHLBI_ROLE="arn:aws:iam::714862078411:role/nih-nhlbi-TopMed-EC2Access-S3" ETL_ROLE="arn:aws:iam::736265540791:role/dbgap-etl" SRC="s3://nih-nhlbi-bdc-recover-adult-phs003463-v6-r1-c1/data/DHDR/" DEST="s3://avillach-73-bdcatalyst-etl/recover_adult/dhdr/" WORK="${WORK:-$HOME/dhdr-pull}"; mkdir -p "$WORK/dhdr" assume(){ local c; c=$(aws sts assume-role --duration-seconds 3600 --role-arn "$1" --role-session-name "$2" --output json) export AWS_ACCESS_KEY_ID=$(jq -r .Credentials.AccessKeyId <<<"$c") AWS_SECRET_ACCESS_KEY=$(jq -r .Credentials.SecretAccessKey <<<"$c") AWS_SESSION_TOKEN=$(jq -r .Credentials.SessionToken <<<"$c"); } drop(){ unset AWS_ACCESS_KEY_ID AWS_SECRET_ACCESS_KEY AWS_SESSION_TOKEN; } export AWS_MAX_ATTEMPTS=10 AWS_RETRY_MODE=adaptive AWS_S3_MAX_CONCURRENT_REQUESTS=64
assume "$NHLBI_ROLE" dhdr-pull aws s3 sync --no-progress "$SRC" "$WORK/dhdr/" --exclude "*" --include "dataset_*/*/part-0.parquet" drop echo "local part-0 files: $(find "$WORK/dhdr" -name part-0.parquet | wc -l) (expected 31723)"
assume "$ETL_ROLE" dhdr-push aws s3 sync --no-progress "$WORK/dhdr/" "$DEST" --exclude "*" --include "dataset_*/*/part-0.parquet" echo "73 part-0 files: $(aws s3 ls "$DEST" --recursive | grep -c '/part-0.parquet') (expected 31723)" aws s3 ls "$DEST" --recursive | awk '/part-0.parquet/{split($4,p,"/"); n[p[3]]++; b[p[3]]+=$3} END{for(d in n) printf "%-48s %6d %8.2f GB\n", d, n[d], b[d]/1e9}' | sort drop
